class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        lo = -10**18
        hi = 10**18
        base = original[0]

        for i, value in enumerate(original):
            diff = value - base
            lo = max(lo, bounds[i][0] - diff)
            hi = min(hi, bounds[i][1] - diff)

        return max(0, hi - lo + 1)
